"use client";

import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cn } from "@/lib/utils";
import { decimalFor, matchText, type GlyphKind } from "./lib/match";
import { resolveOptions, type TextMorphOptions } from "./lib/options";
import "./text-morph.css";

/*
 * Animated text for labels that change in place.
 *
 * The server renders the label already split into one span per glyph, as
 * fixed HTML that this component owns from then on. The browser receives
 * identical markup, so hydration changes nothing and nothing is measured at
 * load. Work happens only when the value changes:
 *
 *   1. Snapshot every visible glyph's on-screen box, including whatever
 *      animation it's mid-way through. Starting from there is what makes a
 *      change that lands mid-animation pick up smoothly instead of jumping.
 *   2. Reuse the glyph nodes the old and new text share, create the new
 *      ones, and move the removed ones to a ghost layer to animate out.
 *   3. Measure the final layout, then animate each glyph from its snapshot.
 *
 * The box width eases with a CSS transition, which always retargets from its
 * current value. When the box resizes, a pinned or centred container moves
 * its left edge; the stage rides the opposite way on the same curve, so the
 * glyphs never drift with it.
 */

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function graphemes(text: string): string[] {
  return segmenter
    ? Array.from(segmenter.segment(text), (s) => s.segment)
    : Array.from(text);
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function glyphsHtml(text: string): string {
  return graphemes(text)
    .map((g) => `<span data-glyph>${escapeHtml(g)}</span>`)
    .join("");
}

function createGlyph(text: string): HTMLSpanElement {
  const span = document.createElement("span");
  span.setAttribute("data-glyph", "");
  span.textContent = text;
  return span;
}

type VisualState = {
  rect: DOMRect;
  opacity: number;
  scale: string;
  rotate: string;
  filter: string;
};

function visualState(node: HTMLElement): VisualState {
  const style = getComputedStyle(node);
  return {
    rect: node.getBoundingClientRect(),
    opacity: Number(style.opacity),
    scale: style.scale === "none" ? "1" : style.scale,
    rotate: style.rotate === "none" ? "0deg" : style.rotate,
    filter: style.filter === "none" ? "blur(0px)" : style.filter,
  };
}

/**
 * Stagger delays for the glyphs that change. `each`: every successive glyph
 * `ms` later. `spread` (Scritto's sweep): delay from where the glyph sits,
 * across `ms` over the changed stretch only, so a one-digit change in a long
 * number isn't left waiting, and a glyph leaving and its replacement in the
 * same spot cross over together. `left` is measured from the box's start.
 */
function staggerDelays(
  o: TextMorphOptions,
  entering: number[],
  leaving: number[],
): { entering: number[]; leaving: number[] } {
  if (o.stagger.mode === "each") {
    return {
      entering: entering.map((_, k) => k * o.stagger.ms),
      leaving: leaving.map((_, k) => k * o.stagger.ms),
    };
  }
  const all = [...entering, ...leaving];
  const min = Math.min(...all);
  const span = Math.max(...all) - min;
  const at = (left: number): number =>
    span > 0 ? (o.stagger.ms * (left - min)) / span : 0;
  return { entering: entering.map(at), leaving: leaving.map(at) };
}

/**
 * Transform keyframe for a glyph away from home: `offset` is 1 below the
 * line, -1 above. Morph letters scale in place; morph digits roll whole
 * lines (`line` is the line height in px).
 */
function awayState(
  o: TextMorphOptions,
  kind: GlyphKind,
  offset: 1 | -1,
  line: number,
): Keyframe {
  if (o.mode === "roll") {
    return {
      translate: `0 ${offset * o.roll.distance}em`,
      scale: String(o.roll.scale),
      rotate: `${o.roll.rotate}deg`,
    };
  }
  if (kind === "number") {
    return {
      translate: `0 ${offset * o.morph.digits.distance * line}px`,
      scale: "1",
      rotate: "0deg",
    };
  }
  return { translate: "0 0", scale: String(o.morph.scale), rotate: "0deg" };
}

/** Fade timings for a glyph of this kind. */
function fadesFor(
  o: TextMorphOptions,
  kind: GlyphKind,
): {
  fadeIn: TextMorphOptions["fadeIn"];
  fadeOut: TextMorphOptions["fadeOut"];
} {
  if (o.mode === "morph" && kind === "number") {
    return {
      fadeIn: { ...o.morph.digits.fadeIn, delay: 0 },
      fadeOut: o.morph.digits.fadeOut,
    };
  }
  return { fadeIn: o.fadeIn, fadeOut: o.fadeOut };
}
const HOME: Keyframe = { translate: "0 0", scale: "1", rotate: "0deg" };

/** Whether a change here would be seen: rendered, and in the viewport. */
function isOnScreen(el: HTMLElement): boolean {
  if (el.checkVisibility && !el.checkVisibility()) return false;
  const rect = el.getBoundingClientRect();
  return (
    rect.bottom > 0 &&
    rect.right > 0 &&
    rect.top < window.innerHeight &&
    rect.left < window.innerWidth
  );
}

/** Pending "drop the explicit width" timers, per root. */
const settleTimers = new WeakMap<HTMLElement, number>();

/** The edge fade's ramp, and how far past the box edge it ends (em). */
const EDGE_RAMP = 0.3;
const EDGE_SLACK = 0.4;
/** Room around a ghost for its blur, tilt and scale (em). */
const INK_MARGIN = 0.3;

type Side = "start" | "end";

/**
 * Whether old ink escaping the box on this side would land on something:
 * a neighbour on the line, or the edge of the box that holds the value (a
 * pill, a card, a clipping wrapper). With room around it, ink is left to
 * dissolve on its own opacity. Reads the final layout.
 */
function inkEscapes(root: HTMLElement, side: Side, inkEdge: number): boolean {
  let el: Element = root;
  for (let depth = 0; depth < 8; depth++) {
    let sibling = side === "end" ? el.nextSibling : el.previousSibling;
    while (sibling) {
      const visible =
        sibling instanceof Element
          ? sibling.getBoundingClientRect().width >= 1
          : Boolean(sibling.textContent?.trim());
      if (visible) return true;
      sibling = side === "end" ? sibling.nextSibling : sibling.previousSibling;
    }
    const parent = el.parentElement;
    if (!parent) return false;
    const style = getComputedStyle(parent);
    if (!style.display.startsWith("inline") && style.display !== "contents") {
      const box = parent.getBoundingClientRect();
      if (side === "end") {
        const edge =
          box.right -
          parseFloat(style.borderRightWidth) -
          parseFloat(style.paddingRight);
        return inkEdge > edge + 0.5;
      }
      const edge =
        box.left +
        parseFloat(style.borderLeftWidth) +
        parseFloat(style.paddingLeft);
      return inkEdge < edge - 0.5;
    }
    el = parent;
  }
  return false;
}

/** A ghost's place in stage coordinates, kept in custom properties. */
function ghostPlace(node: HTMLElement): { x: number; y: number } {
  return {
    x: parseFloat(node.style.getPropertyValue("--x")) || 0,
    y: parseFloat(node.style.getPropertyValue("--y")) || 0,
  };
}
function placeGhost(node: HTMLElement, x: number, y: number): void {
  node.style.setProperty("--x", `${x}px`);
  node.style.setProperty("--y", `${y}px`);
}

/** Lift the edge fade once the last ghost has left. */
function disarm(ghostLayer: HTMLElement): void {
  for (const animation of ghostLayer.getAnimations()) animation.cancel();
  ghostLayer.style.removeProperty("--text-morph-edge");
  delete ghostLayer.dataset.armed;
}

function morphTo(
  root: HTMLElement,
  stage: HTMLElement,
  glyphLayer: HTMLElement,
  ghostLayer: HTMLElement,
  value: string,
  o: TextMorphOptions,
  decimal: string,
  animate: boolean,
): Animation[] {
  // Everything this change starts, so the caller can tell when it's over.
  const started: Animation[] = [];
  const run = (
    el: Element,
    keyframes: Keyframe[],
    timing: KeyframeAnimationOptions,
  ): Animation => {
    const animation = el.animate(keyframes, timing);
    started.push(animation);
    return animation;
  };
  const old = Array.from(glyphLayer.children) as HTMLElement[];
  const next = graphemes(value);

  // 1. Where everything is on screen right now.
  const rootBefore = root.getBoundingClientRect();
  const stageBefore = stage.getBoundingClientRect();
  const before = new Map(old.map((node) => [node, visualState(node)]));
  const ghosts = Array.from(ghostLayer.children) as HTMLElement[];
  const ghostRects = ghosts.map((node) => node.getBoundingClientRect());

  // 2. New glyph list.
  const match = matchText(
    o.mode,
    old.map((node) => node.textContent ?? ""),
    next,
    { numbers: o.numbers, decimal, trend: o.trend },
  );
  const used = new Set(match.kept);
  const kept = match.kept.map((from) => (from === -1 ? null : old[from]));
  const removed = old.filter((_, i) => !used.has(i));
  const removedKinds = old.flatMap((_, i) =>
    used.has(i) ? [] : [match.oldKinds[i]],
  );
  const nodes = next.map((glyph, i) => kept[i] ?? createGlyph(glyph));
  for (const node of [...nodes, ...removed, stage]) {
    for (const animation of node.getAnimations()) animation.cancel();
  }
  glyphLayer.replaceChildren(...nodes);

  window.clearTimeout(settleTimers.get(root));
  if (!animate) {
    root.style.transition = "";
    root.style.width = "";
    return started;
  }

  // 3. The final layout: the box at its new width, no ride.
  root.style.transition = "none";
  root.style.width = "";
  const width = glyphLayer.getBoundingClientRect().width;
  root.style.width = `${width}px`;
  const rootAfter = root.getBoundingClientRect();
  const stageAfter = stage.getBoundingClientRect();
  const after = nodes.map((node) => node.getBoundingClientRect());
  const line = glyphLayer.getBoundingClientRect().height;
  const em = parseFloat(getComputedStyle(root).fontSize) || 16;

  // Ghosts live in stage coordinates; the stage holds still on screen at
  // its final place for the whole change, so earlier ghosts shift by
  // however far it moved, and hold theirs.
  const shiftX = stageBefore.left - stageAfter.left;
  const shiftY = stageBefore.top - stageAfter.top;
  for (const node of ghosts) {
    const { x, y } = ghostPlace(node);
    placeGhost(node, x + shiftX, y + shiftY);
  }

  // Edge fade: the box (stage coordinates) before and after, and how far
  // old ink reaches past it.
  const boxStart = rootBefore.left - stageAfter.left;
  const boxEnd = rootBefore.right - stageAfter.left;
  const inkRects = [
    ...ghostRects,
    ...removed
      .map((node) => before.get(node)?.rect)
      .filter((r) => r !== undefined),
  ];
  // The glyph boxes decide whether ink sticks out; the room also covers
  // their blur and tilt.
  const glyphStart =
    Math.min(Infinity, ...inkRects.map((r) => r.left)) - stageAfter.left;
  const glyphEnd =
    Math.max(-Infinity, ...inkRects.map((r) => r.right)) - stageAfter.left;
  const inkStart = glyphStart - INK_MARGIN * em;
  const inkEnd = glyphEnd + INK_MARGIN * em;
  const wasArmed = ghostLayer.dataset.armed ?? "";
  const armed = (side: Side): boolean => {
    if (o.edgeFade === "never" || inkRects.length === 0) return false;
    if (wasArmed.includes(side)) return true;
    const travels =
      side === "start"
        ? Math.abs(boxStart) > 0.5
        : Math.abs(boxEnd - width) > 0.5;
    const overhangs =
      side === "start" ? glyphStart < -0.5 : glyphEnd > width + 0.5;
    if (!travels || !overhangs) return false;
    return (
      o.edgeFade === "always" ||
      inkEscapes(
        root,
        side,
        stageAfter.left + (side === "start" ? glyphStart : glyphEnd),
      )
    );
  };
  const armStart = armed("start");
  const armEnd = armed("end");

  // A rise brings new glyphs up from below and sends old ones up and away.
  const arrive = match.trend;
  const leave = match.trend === 1 ? -1 : 1;

  // Width: back to where it visibly was, then ease to the new width.
  root.style.width = `${rootBefore.width}px`;
  void root.offsetWidth;
  root.style.transition = `width ${o.width.duration}ms ${o.width.easing}`;
  root.style.width = `${width}px`;
  started.push(...root.getAnimations());
  settleTimers.set(
    root,
    window.setTimeout(() => {
      root.style.transition = "";
      root.style.width = "";
    }, o.width.duration + 50),
  );

  // The box's left edge moves while it resizes (a centred pill, a
  // right-pinned button); ride the other way on the same curve.
  const ride = rootAfter.left - rootBefore.left;
  if (Math.abs(ride) > 0.5) {
    run(stage, [{ translate: `${ride}px 0` }, { translate: "0 0" }], {
      duration: o.width.duration,
      easing: o.width.easing,
    });
  }

  const motion = { duration: o.motion.duration, easing: o.motion.easing };
  const blur = `blur(${o.blur}em)`;
  const delays = staggerDelays(
    o,
    nodes.flatMap((_, i) => (kept[i] ? [] : [after[i].left - rootAfter.left])),
    removed.map(
      (node) =>
        (before.get(node)?.rect.left ?? rootBefore.left) - rootBefore.left,
    ),
  );

  // Shared glyphs slide from wherever they were, including mid-animation.
  let entering = 0;
  nodes.forEach((node, i) => {
    const was = kept[i] ? before.get(node) : undefined;
    const kind = match.nextKinds[i];
    const { fadeIn } = fadesFor(o, kind);
    if (!was) {
      const delay = delays.entering[entering++];
      run(node, [awayState(o, kind, arrive, line), HOME], {
        ...motion,
        delay,
        fill: "backwards",
      });
      run(
        node,
        [
          { opacity: 0, filter: blur },
          { opacity: 1, filter: "blur(0px)" },
        ],
        {
          duration: fadeIn.duration,
          easing: fadeIn.easing,
          delay: delay + fadeIn.delay,
          fill: "backwards",
        },
      );
      return;
    }
    const dx = was.rect.left - after[i].left;
    const dy = was.rect.top - after[i].top;
    if (
      Math.abs(dx) > 0.5 ||
      Math.abs(dy) > 0.5 ||
      was.scale !== "1" ||
      was.rotate !== "0deg"
    ) {
      run(
        node,
        [
          {
            translate: `${dx}px ${dy}px`,
            scale: was.scale,
            rotate: was.rotate,
          },
          HOME,
        ],
        motion,
      );
    }
    if (was.opacity < 0.999 || was.filter !== "blur(0px)") {
      run(
        node,
        [
          { opacity: was.opacity, filter: was.filter },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: fadeIn.duration, easing: fadeIn.easing },
      );
    }
  });

  // The ghost layer reaches past all the ink (a mask cuts whatever falls
  // outside its element), and wears a band on each armed edge that follows
  // the box edge on the width's curve, ending a little past it.
  const slack = EDGE_SLACK * em;
  const room = Math.ceil(
    Math.max(
      0,
      -inkStart,
      inkEnd - width,
      -(boxStart - slack),
      boxEnd + slack - width,
    ) + 1,
  );
  ghostLayer.style.setProperty("--text-morph-room", `${room}px`);
  for (const animation of ghostLayer.getAnimations()) animation.cancel();
  if (armStart || armEnd) {
    const ramp = EDGE_RAMP * em;
    const span = width + 2 * room;
    const window = (start: number, end: number) => {
      const left = armStart ? room + start - slack : 0;
      const right = armEnd ? room + end + slack : span;
      return {
        maskPosition: `0 0, ${left}px 0`,
        maskSize: `100% 100%, ${right - left}px 100%`,
      };
    };
    ghostLayer.dataset.armed = `${armStart ? "start " : ""}${armEnd ? "end" : ""}`;
    ghostLayer.style.setProperty(
      "--text-morph-edge",
      `linear-gradient(to right, ${armStart ? `transparent, #000 ${ramp}px` : "#000"}, ${
        armEnd ? `#000 calc(100% - ${ramp}px), transparent` : "#000"
      })`,
    );
    run(ghostLayer, [window(boxStart, boxEnd), window(0, width)], {
      duration: o.width.duration,
      easing: o.width.easing,
      fill: "forwards",
    });
  } else {
    disarm(ghostLayer);
  }

  // Removed glyphs leave from where they were, in the ghost layer.
  removed.forEach((node, i) => {
    const was = before.get(node);
    if (!was) return;
    placeGhost(
      node,
      was.rect.left - stageAfter.left,
      was.rect.top - stageAfter.top,
    );
    ghostLayer.append(node);
    const kind = removedKinds[i];
    const { fadeOut } = fadesFor(o, kind);
    const delay = delays.leaving[i];
    const move = run(
      node,
      [
        { translate: "0 0", scale: was.scale, rotate: was.rotate },
        awayState(o, kind, leave, line),
      ],
      { ...motion, delay, fill: "forwards" },
    );
    const out = run(
      node,
      [
        { opacity: was.opacity, filter: was.filter },
        { opacity: 0, filter: blur },
      ],
      {
        duration: fadeOut.duration,
        easing: fadeOut.easing,
        delay,
        fill: "forwards",
      },
    );
    const finish = (): void => {
      if (node.parentNode === ghostLayer) node.remove();
      if (ghostLayer.childElementCount === 0) disarm(ghostLayer);
    };
    // Cancelled by a later change, which already moved on without it.
    Promise.all([move.finished, out.finished]).then(finish, finish);
  });
  return started;
}

export type TextMorphProps = Omit<
  useRender.ComponentProps<"span">,
  "children" | "onAnimationStart" | "onAnimationEnd"
> & {
  /** The text. A number is formatted with `locale` and `decimals`. */
  value: string | number;
  options?: Partial<TextMorphOptions>;
  /**
   * Formats a number `value` and names the decimal separator numbers are
   * aligned on. Fixed rather than the browser's, so the server and the
   * browser render the same text.
   */
  locale?: string;
  /** Fraction digits for a number `value`. */
  decimals?: number;
  /** Swap the text without animating. */
  disabled?: boolean;
  /** Swap without animating when the reader prefers reduced motion. */
  respectReducedMotion?: boolean;
  /** A change started animating. */
  onAnimationStart?: () => void;
  /**
   * A change finished, every glyph and the box settled. Fires right away
   * for a change that didn't animate (disabled, reduced motion, off screen).
   * Each change ends in exactly one of this and `onAnimationCancel`.
   */
  onAnimationComplete?: () => void;
  /** A change was interrupted by the next one. */
  onAnimationCancel?: () => void;
};

function formatValue(
  value: string | number,
  locale: string,
  decimals: number | undefined,
): string {
  if (typeof value === "string") return value;
  return new Intl.NumberFormat(
    locale,
    decimals === undefined
      ? undefined
      : { minimumFractionDigits: decimals, maximumFractionDigits: decimals },
  ).format(value);
}

export function TextMorph({
  value: rawValue,
  options,
  locale = "en",
  decimals,
  disabled = false,
  respectReducedMotion = true,
  onAnimationStart,
  onAnimationComplete,
  onAnimationCancel,
  className,
  render,
  ...props
}: TextMorphProps): React.ReactElement {
  const value = formatValue(rawValue, locale, decimals);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const stageRef = React.useRef<HTMLSpanElement>(null);
  const glyphsRef = React.useRef<HTMLSpanElement>(null);
  const ghostsRef = React.useRef<HTMLSpanElement>(null);
  // Set once: after that this component owns the glyph markup.
  const [initialHtml] = React.useState(() => ({ __html: glyphsHtml(value) }));
  const shown = React.useRef(value);
  const resolved = resolveOptions(options);
  const optionsRef = React.useRef(resolved);
  const latest = React.useRef({
    disabled,
    respectReducedMotion,
    onAnimationStart,
    onAnimationComplete,
    onAnimationCancel,
  });
  React.useLayoutEffect(() => {
    optionsRef.current = resolved;
    latest.current = {
      disabled,
      respectReducedMotion,
      onAnimationStart,
      onAnimationComplete,
      onAnimationCancel,
    };
  });

  // The change in flight, so the next one can cancel it.
  const inFlight = React.useRef<(() => void) | null>(null);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    const stage = stageRef.current;
    const glyphs = glyphsRef.current;
    const ghosts = ghostsRef.current;
    if (!root || !stage || !glyphs || !ghosts || value === shown.current)
      return;
    shown.current = value;
    inFlight.current?.();
    inFlight.current = null;

    const current = latest.current;
    const reduce =
      current.respectReducedMotion &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const started = morphTo(
      root,
      stage,
      glyphs,
      ghosts,
      value,
      optionsRef.current,
      decimalFor(locale),
      !current.disabled && !reduce && isOnScreen(root),
    );
    if (started.length === 0) {
      current.onAnimationComplete?.();
      return;
    }

    current.onAnimationStart?.();
    let over = false;
    const cancel = (): void => {
      if (over) return;
      over = true;
      latest.current.onAnimationCancel?.();
    };
    inFlight.current = cancel;
    void Promise.allSettled(started.map((a) => a.finished)).then(() => {
      if (over) return;
      over = true;
      if (inFlight.current === cancel) inFlight.current = null;
      latest.current.onAnimationComplete?.();
    });
  }, [value, locale]);

  const defaultProps = {
    "data-slot": "text-morph",
    "data-mode": resolved.mode,
    className: cn("text-morph", className),
    children: (
      <>
        <span className="sr-only">{value}</span>
        <span ref={stageRef} aria-hidden="true" className="text-morph-stage">
          <span
            ref={glyphsRef}
            className="text-morph-glyphs"
            dangerouslySetInnerHTML={initialHtml}
          />
          <span ref={ghostsRef} className="text-morph-ghosts" />
        </span>
      </>
    ),
  };

  return useRender({
    defaultTagName: "span",
    render,
    ref: rootRef,
    props: mergeProps<"span">(defaultProps, props),
  });
}

export type { TextMorphMode, TextMorphOptions } from "./lib/options";

import type { TextMorphMode } from "./options";

/*
 * Which glyphs of the old text survive into the new one. Pure: works on
 * grapheme strings, so it can be tested without a DOM.
 *
 * Numbers are matched by place value (torph): the digits line up on the
 * decimal point, so 1,204 → 1,318 keeps the thousands and the comma, and a
 * digit that changes rolls in place. Everything else is matched by the
 * mode's text rule.
 */

/** `number`: part of a number matched by place value. */
export type GlyphKind = "text" | "number";

export type MatchResult = {
  /** For each new glyph, the index of the old glyph it keeps, or -1. */
  kept: number[];
  nextKinds: GlyphKind[];
  oldKinds: GlyphKind[];
  /** 1: the value went up (new glyphs arrive from below), -1: down. */
  trend: 1 | -1;
};

export type MatchOptions = {
  /** Match numbers by place value. */
  numbers: boolean;
  /** The locale's decimal separator. */
  decimal: string;
  /** 1 up, -1 down, 0 read it off the numbers. */
  trend: -1 | 0 | 1;
};

type NumberToken = { start: number; end: number };

const SIGN = "+-−";
const GROUP = ".,'   ";
const DIGIT = /^\d$/;
const CURRENCY = /^\p{Sc}$/u;

const isDigit = (g: string): boolean => DIGIT.test(g);

/**
 * Numbers in a grapheme list: an optional sign and currency symbol, digits
 * with group or decimal separators between them, and an optional `%`.
 */
export function findNumbers(glyphs: string[]): NumberToken[] {
  const tokens: NumberToken[] = [];
  let i = 0;
  while (i < glyphs.length) {
    if (!isDigit(glyphs[i])) {
      i++;
      continue;
    }
    let start = i;
    // Leading currency symbol, then sign, either order.
    for (let k = 0; k < 2; k++) {
      const before = glyphs[start - 1];
      if (before && (CURRENCY.test(before) || SIGN.includes(before))) start--;
    }
    let end = i + 1;
    while (end < glyphs.length) {
      if (isDigit(glyphs[end])) end++;
      else if (GROUP.includes(glyphs[end]) && isDigit(glyphs[end + 1] ?? ""))
        end += 2;
      else break;
    }
    if (glyphs[end] === "%") end++;
    tokens.push({ start, end });
    i = end;
  }
  return tokens;
}

/**
 * A key per glyph of one number, naming its place: `i2` is the hundreds,
 * `g3` the separator left of them, `f0` the first decimal, `d` the point.
 * Glyphs with the same key and character are the same glyph.
 */
export function placeKeys(glyphs: string[], decimal: string): string[] {
  const first = glyphs.findIndex(isDigit);
  let last = glyphs.length - 1;
  while (last > first && !isDigit(glyphs[last])) last--;
  let point = -1;
  for (let i = last; i > first; i--) {
    if (glyphs[i] === decimal) {
      point = i;
      break;
    }
  }
  const intEnd = point === -1 ? last + 1 : point;

  const keys: string[] = new Array(glyphs.length);
  for (let i = 0; i < first; i++) keys[i] = `p${first - i}`;
  for (let i = last + 1; i < glyphs.length; i++) keys[i] = `s${i - last}`;
  let place = 0;
  for (let i = intEnd - 1; i >= first; i--) {
    if (isDigit(glyphs[i])) keys[i] = `i${place++}`;
    else keys[i] = `g${place}`;
  }
  if (point !== -1) {
    keys[point] = "d";
    let decimals = 0;
    for (let i = point + 1; i <= last; i++) {
      if (isDigit(glyphs[i])) keys[i] = `f${decimals++}`;
      else keys[i] = `h${decimals}`;
    }
  }
  return keys;
}

/** The numeric value of a number token, or NaN. */
export function parseNumber(glyphs: string[], decimal: string): number {
  let text = "";
  for (const g of glyphs) {
    if (isDigit(g)) text += g;
    else if (g === decimal) text += ".";
    else if (g === "-" || g === "−") text = `-${text}`;
  }
  return Number(text);
}

/** Keep the shared start and end. Returns [newIndex, oldIndex] pairs. */
function matchEnds(old: string[], next: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (
    start < old.length &&
    start < next.length &&
    old[start] === next[start]
  ) {
    pairs.push([start, start]);
    start++;
  }
  let end = 0;
  while (
    end < old.length - start &&
    end < next.length - start &&
    old[old.length - 1 - end] === next[next.length - 1 - end]
  ) {
    pairs.push([next.length - 1 - end, old.length - 1 - end]);
    end++;
  }

  // Between them, one shared run flush with neither end (Scritto's
  // floating run): xxlightxx → yylightyy keeps "light". It must be at
  // least two glyphs (one shared letter is a coincidence) and may travel at
  // most its own length plus two slots, so a word never swims across the
  // value while everything around it dissolves.
  const run = floatingRun(
    old.slice(start, old.length - end),
    next.slice(start, next.length - end),
  );
  if (run) {
    for (let k = 0; k < run.length; k++) {
      pairs.push([start + run.to + k, start + run.from + k]);
    }
  }
  return pairs;
}

const MIN_RUN = 2;
const RUN_SLACK = 2;

/** The longest shared run within its travel cap; the shorter trip on ties. */
export function floatingRun(
  old: string[],
  next: string[],
): { from: number; to: number; length: number } | null {
  let best: { from: number; to: number; length: number } | null = null;
  // lengths[j]: the shared run ending at old[i - 1] and next[j - 1].
  let previous = new Array<number>(next.length + 1).fill(0);
  for (let i = 1; i <= old.length; i++) {
    const lengths = new Array<number>(next.length + 1).fill(0);
    for (let j = 1; j <= next.length; j++) {
      if (old[i - 1] !== next[j - 1]) continue;
      const length = previous[j - 1] + 1;
      lengths[j] = length;
      const from = i - length;
      const to = j - length;
      const travel = Math.abs(to - from);
      if (length < MIN_RUN || travel > length + RUN_SLACK) continue;
      if (
        !best ||
        length > best.length ||
        (length === best.length && travel < Math.abs(best.to - best.from))
      ) {
        best = { from, to, length };
      }
    }
    previous = lengths;
  }
  return best;
}

/** Match each glyph to the first unused old copy of it, in order. */
function matchAnywhere(old: string[], next: string[]): [number, number][] {
  const pool = new Map<string, number[]>();
  old.forEach((glyph, i) => pool.set(glyph, [...(pool.get(glyph) ?? []), i]));
  const pairs: [number, number][] = [];
  next.forEach((glyph, i) => {
    const from = pool.get(glyph)?.shift();
    if (from !== undefined) pairs.push([i, from]);
  });
  return pairs;
}

export function matchText(
  mode: TextMorphMode,
  old: string[],
  next: string[],
  options: MatchOptions,
): MatchResult {
  const kept = next.map(() => -1);
  const oldKinds: GlyphKind[] = old.map(() => "text");
  const nextKinds: GlyphKind[] = next.map(() => "text");
  const oldNumbers = options.numbers ? findNumbers(old) : [];
  const nextNumbers = options.numbers ? findNumbers(next) : [];
  const paired = Math.min(oldNumbers.length, nextNumbers.length);

  // Numbers, paired in order, matched by place.
  let trend: 1 | -1 | 0 = options.trend;
  for (let n = 0; n < paired; n++) {
    const a = oldNumbers[n];
    const b = nextNumbers[n];
    const aGlyphs = old.slice(a.start, a.end);
    const bGlyphs = next.slice(b.start, b.end);
    const byKey = new Map<string, number>();
    placeKeys(aGlyphs, options.decimal).forEach((key, i) =>
      byKey.set(key, a.start + i),
    );
    placeKeys(bGlyphs, options.decimal).forEach((key, i) => {
      const from = byKey.get(key);
      if (from !== undefined && old[from] === next[b.start + i]) {
        kept[b.start + i] = from;
      }
    });
    for (let i = a.start; i < a.end; i++) oldKinds[i] = "number";
    for (let i = b.start; i < b.end; i++) nextKinds[i] = "number";

    if (trend === 0) {
      const before = parseNumber(aGlyphs, options.decimal);
      const after = parseNumber(bGlyphs, options.decimal);
      if (after !== before) trend = after > before ? 1 : -1;
    }
  }

  // Everything else, by the mode's text rule.
  const oldText = old.flatMap((_, i) => (oldKinds[i] === "text" ? [i] : []));
  const nextText = next.flatMap((_, i) => (nextKinds[i] === "text" ? [i] : []));
  const match = mode === "roll" ? matchEnds : matchAnywhere;
  for (const [to, from] of match(
    oldText.map((i) => old[i]),
    nextText.map((i) => next[i]),
  )) {
    kept[nextText[to]] = oldText[from];
  }

  // A value that gains or loses a number, or changes none, reads as a rise.
  return { kept, nextKinds, oldKinds, trend: trend === -1 ? -1 : 1 };
}

const decimals = new Map<string, string>();

/** The decimal separator for a locale. */
export function decimalFor(locale: string): string {
  let decimal = decimals.get(locale);
  if (decimal === undefined) {
    decimal =
      new Intl.NumberFormat(locale)
        .formatToParts(1.1)
        .find((part) => part.type === "decimal")?.value ?? ".";
    decimals.set(locale, decimal);
  }
  return decimal;
}

export type TextMorphMode = "roll" | "morph";

/** One CSS timing: a duration in ms and any CSS easing, `linear()` included. */
export type Timing = { duration: number; easing: string };

export type TextMorphOptions = {
  /**
   * `roll` keeps the old and new text's shared start and end, and rolls the
   * glyphs between vertically, on Scritto's defaults. `morph` matches letters
   * anywhere: shared ones slide to their new place, the rest scale and fade
   * in place, on torph's defaults. Each mode brings its own defaults.
   */
  mode: TextMorphMode;
  /** Glyph movement: roll travel, enter/exit scale, shared glyphs sliding. */
  motion: Timing;
  /** Opacity and blur of arriving glyphs, optionally starting late. */
  fadeIn: Timing & { delay: number };
  /** Opacity and blur of leaving glyphs. */
  fadeOut: Timing;
  /** The box's width. */
  width: Timing;
  /**
   * `each`: every successive entering or leaving glyph starts `ms` later.
   * `spread`: a sweep from left to right across `ms` in total, by where
   * each glyph sits along the changed stretch.
   */
  stagger: { mode: "each" | "spread"; ms: number };
  /** Roll: travel (em), and the scale and tilt glyphs arrive and leave with. */
  roll: { distance: number; scale: number; rotate: number };
  /**
   * Morph: the scale letters grow from and shrink to. Digits of a number
   * roll instead, `distance` line heights, on their own fades.
   */
  morph: {
    scale: number;
    digits: { distance: number; fadeIn: Timing; fadeOut: Timing };
  };
  /** Blur on arriving and leaving glyphs, in em. */
  blur: number;
  /**
   * Match numbers by place value: digits line up on the decimal point, so
   * only the ones that changed roll.
   */
  numbers: boolean;
  /**
   * Which way glyphs roll: 1 up (new ones arrive from below), -1 down, 0
   * read it off the value (a number that grew rolls up).
   */
  trend: -1 | 0 | 1;
  /**
   * Fade old ink at an edge the box is shrinking away from. `auto` only
   * where it would land on something: a neighbour on the line, or the edge
   * of the pill or card holding the value.
   */
  edgeFade: "auto" | "always" | "never";
};

/** torph's digits: a full line of travel, fading out over 45% of the
 * duration and in over the first 25%. */
const TORPH_DIGITS: TextMorphOptions["morph"]["digits"] = {
  distance: 1,
  fadeIn: { duration: 100, easing: "linear" },
  fadeOut: { duration: 180, easing: "linear" },
};

/** The curve the box width eases on: fast out, no overshoot. */
export const WIDTH_EASING = "cubic-bezier(0.22, 1, 0.36, 1)";
/** Ease-out expo: torph's movement, width and everything. */
export const EXPO_EASING = "cubic-bezier(0.19, 1, 0.22, 1)";

/**
 * Scritto 0.1.0's defaults, from its source: a 550ms hand-tuned spring (1.5%
 * overshoot) on transform, opacity and blur alike; glyphs travel 0.35em while
 * scaling to 0.6 and tilting 2deg, blurred 0.1em; delays fan out over 30% of
 * the duration; the box eases on its own non-overshooting curve.
 */
const SCRITTO_SPRING =
  "linear(0,.1052,.3155,.532,.7112,.8414,.9265,.9765,1.0023,1.013,1.0151,1.0133,1.01,1.0068,1.0041,1.0022,1.001,1)";
export const SCRITTO_OPTIONS: TextMorphOptions = {
  mode: "roll",
  motion: { duration: 550, easing: SCRITTO_SPRING },
  fadeIn: { duration: 550, easing: SCRITTO_SPRING, delay: 0 },
  fadeOut: { duration: 550, easing: SCRITTO_SPRING },
  width: { duration: 550, easing: WIDTH_EASING },
  stagger: { mode: "spread", ms: 165 },
  roll: { distance: 0.35, scale: 0.6, rotate: 2 },
  morph: { scale: 0.6, digits: TORPH_DIGITS },
  blur: 0.1,
  numbers: true,
  trend: 0,
  edgeFade: "auto",
};

/**
 * torph 0.1.3's defaults, from its source: 400ms ease-out expo for movement
 * and width; arriving and leaving glyphs scale by 0.95; opacity is linear,
 * leaving over the first quarter of the duration and arriving over half of it
 * from a quarter in; no blur, no stagger.
 */
export const TORPH_OPTIONS: TextMorphOptions = {
  mode: "morph",
  motion: { duration: 400, easing: EXPO_EASING },
  fadeIn: { duration: 200, easing: "linear", delay: 100 },
  fadeOut: { duration: 100, easing: "linear" },
  width: { duration: 400, easing: EXPO_EASING },
  stagger: { mode: "each", ms: 0 },
  roll: { distance: 0.35, scale: 0.95, rotate: 0 },
  morph: { scale: 0.95, digits: TORPH_DIGITS },
  blur: 0,
  numbers: true,
  trend: 0,
  edgeFade: "auto",
};

/** Each mode brings its own defaults: roll is Scritto's, morph is torph's. */
export const MODE_DEFAULTS: Record<TextMorphMode, TextMorphOptions> = {
  roll: SCRITTO_OPTIONS,
  morph: TORPH_OPTIONS,
};

/** Production: morph. */
export const DEFAULT_OPTIONS: TextMorphOptions = MODE_DEFAULTS.morph;

/** Options for `overrides`, filled in from the chosen mode's defaults. */
export function resolveOptions(
  overrides: Partial<TextMorphOptions> = {},
): TextMorphOptions {
  return {
    ...MODE_DEFAULTS[overrides.mode ?? DEFAULT_OPTIONS.mode],
    ...overrides,
  };
}

/** The same look on a shorter clock (every duration, delay and stagger). */
export function faster(o: TextMorphOptions, factor: number): TextMorphOptions {
  const t = (timing: Timing): Timing => ({
    ...timing,
    duration: Math.round(timing.duration * factor),
  });
  return {
    ...o,
    motion: t(o.motion),
    fadeIn: { ...t(o.fadeIn), delay: Math.round(o.fadeIn.delay * factor) },
    fadeOut: t(o.fadeOut),
    width: t(o.width),
    stagger: { ...o.stagger, ms: Math.round(o.stagger.ms * factor) },
    morph: {
      ...o.morph,
      digits: {
        ...o.morph.digits,
        fadeIn: t(o.morph.digits.fadeIn),
        fadeOut: t(o.morph.digits.fadeOut),
      },
    },
  };
}

/* TextMorph (components/docs/text-morph). The server renders one span per
   glyph, the same markup the browser keeps, so these styles apply from first
   paint and nothing shifts on hydration. */

.text-morph {
  --text-morph-fade-y: linear-gradient(
    to bottom,
    transparent,
    #000 0.3em,
    #000 calc(100% - 0.3em),
    transparent
  );
  position: relative;
  display: inline-block;
  max-width: none;
  white-space: nowrap;
  /* Its baseline is its text's, so it lines up with the words around it
     at any font size. */
  vertical-align: baseline;
}

.text-morph-stage {
  position: relative;
  display: inline-block;
}

/* Room above and below for glyphs travelling in and out, faded at the
   edges, without changing the line the label sits on. The mask sits on the
   layers, not the box: a mask cuts whatever falls outside its element, and
   ghosts reach past the box while it shrinks. */
.text-morph-glyphs {
  display: inline-block;
  white-space: pre;
  padding-block: 0.3em;
  margin-block: -0.3em;
  mask-image: var(--text-morph-fade-y);
}

.text-morph [data-glyph] {
  display: inline-block;
  white-space: pre;
}

/* Ghosts sit at --x/--y in stage coordinates. The layer reaches
   --text-morph-room past the stage on both sides so nothing is cut, and
   wears the edge fade (--text-morph-edge, set per change) only while a
   shrinking box would leave ink over a neighbour. */
.text-morph-ghosts {
  position: absolute;
  inset-block: -0.3em;
  inset-inline: calc(-1 * var(--text-morph-room, 0px));
  pointer-events: none;
  mask-image:
    var(--text-morph-fade-y),
    var(--text-morph-edge, linear-gradient(#000, #000));
  mask-size:
    100% 100%,
    100% 100%;
  mask-repeat: no-repeat;
  mask-composite: intersect;
}
.text-morph-ghosts > [data-glyph] {
  position: absolute;
  left: calc(var(--x, 0px) + var(--text-morph-room, 0px));
  top: calc(var(--y, 0px) + 0.3em);
}
